var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.OpenLogFiles", Doc: "OpenLogFiles opens the log files for modes and levels of the looper,\nbased on the lists of level names, ordered by modes in numerical order.\nThe netName and runName are used for naming the file, along with\nthe mode_level in lower case.\nThe tables are the [tensorfs.DirTable] of each stats directory,\nwhich caches the table on the directory node, so that the same\ntable object (and its log file state) is used by the stats\nthat write values into that directory.", Args: []string{"ls", "statsDir", "netName", "runName", "modeLevels"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.CloseLogFiles", Doc: "CloseLogFiles closes all the log files for each mode and level of the looper,\nexcluding given level(s).", Args: []string{"ls", "statsDir", "exclude"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.StatExcludeLevel", Doc: "StatExcludeLevel returns true if given level is among the list of levels to exclude.", Args: []string{"level", "exclude"}, Returns: []string{"bool"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.StatLoopCounters", Doc: "StatLoopCounters adds the counters from each stack, loop level for given\nlooper Stacks to the given tensorfs stats. This is typically the first\nStat to add, so these counters will be used for X axis values.\nThe stat is run with start = true before returning, so that the stats\nare already initialized first before anything else.\nThe first mode's counters (typically Train) are automatically added to all\nsubsequent modes so they automatically track training levels.\n\n  - currentDir is a tensorfs directory to store the current values of each counter.\n  - trialLevel is the Trial level enum, which automatically handles the\n    iteration over ndata parallel trials.\n  - exclude is a list of loop levels to exclude (e.g., Cycle).", Args: []string{"statsDir", "currentDir", "ls", "net", "trialLevel", "exclude"}, Returns: []string{"Enum, start bool)"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.StatRunName", Doc: "StatRunName adds a \"RunName\" stat to every mode and level of looper,\nsubject to exclusion list, which records the current value of the\n\"RunName\" string in currentDir, which identifies the parameters and tag\nfor this run.", Args: []string{"statsDir", "currentDir", "ls", "net", "trialLevel", "exclude"}, Returns: []string{"Enum, start bool)"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.StatTrialName", Doc: "StatTrialName adds a \"TrialName\" stat to the given Trial level in every mode of looper,\nwhich records the current value of the \"TrialName\" string in currentDir, which\ncontains a string description of the current trial.", Args: []string{"statsDir", "currentDir", "ls", "net", "trialLevel"}, Returns: []string{"Enum, start bool)"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/emer/egomlx/egomlx.StatPerTrialMSec", Doc: "StatPerTrialMSec returns a Stats function that reports the number of milliseconds\nper trial, for the given levels and training mode enum values.\nStats will be recorded at levels above the given trial level.", Args: []string{"statsDir", "trainMode", "trialLevel"}, Returns: []string{"Enum, start bool)"}})
